// The frame's assets folder, browsed on the frame: folders and pictures as a
// grid, a page a screen (swipe, or the arrows), a picture on the whole screen
// with a swipe to the next, and a slideshow. Thumbnails are decoded at the
// size of their tile (a 12-megapixel JPEG is scaled as it decodes), one a pass
// after the page shows, and kept while the app lives.
//
// Where you are (the folder, the page, the picture open) is the private
// `spot` field, kept on disk: leave the scene and come back, and it opens
// where you were.

const IMAGES = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'qoi', 'ppm', 'svg', 'webp']
const LIST_MS = 30 * 1000
const SLIDE_SECONDS = 10

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`

const thumbs = new Map() // path -> kept image ref
const failedThumbs = new Set()
let thumbOrder = []
let viewer = { path: '', ref: null }
let listed = { dir: null, at: 0, entries: [] }
let lastPageKey = ''
let chrome = true
let slideAt = 0

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)
const extOf = (name) => (name.includes('.') ? name.split('.').pop().toLowerCase() : '')
const isImage = (name) => IMAGES.includes(extOf(name))
const baseName = (path) => path.replace(/\/$/, '').split('/').pop()

// The folder's own entries: folders (ending in "/") first, then pictures,
// then the rest, by name. A runtime before 2026.11.8 lists every file below,
// so its folders are read off the paths.
function entriesOf(dir) {
  if (listed.dir === dir && Date.now() - listed.at < LIST_MS) return listed.entries
  const prefix = dir ? dir + '/' : ''
  const seen = new Set()
  const entries = []
  for (const path of frameos.listAssets(dir, { shallow: true }) || []) {
    if (!path.startsWith(prefix)) continue
    const rest = path.slice(prefix.length)
    const slash = rest.indexOf('/')
    const entry = slash >= 0 && slash < rest.length - 1 ? prefix + rest.slice(0, slash + 1) : path
    if (!seen.has(entry)) {
      seen.add(entry)
      entries.push(entry)
    }
  }
  const rank = (path) => (path.endsWith('/') ? 0 : isImage(path) ? 1 : 2)
  entries.sort((a, b) => rank(a) - rank(b) || baseName(a).toLowerCase().localeCompare(baseName(b).toLowerCase()))
  listed = { dir, at: Date.now(), entries }
  return entries
}

function loadThumb(path, size, limit) {
  const ref = frameos.loadAssetImage(path, { keep: true, width: size, height: size, fit: 'cover' })
  if (!ref) {
    failedThumbs.add(path)
    return
  }
  thumbs.set(path, ref)
  thumbOrder = thumbOrder.filter((p) => p !== path).concat(path)
  while (thumbOrder.length > limit) {
    const old = thumbOrder.shift()
    frameos.releaseImage(thumbs.get(old))
    thumbs.delete(old)
  }
}

function lookOf(app) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const width = (app.frame.rotate || 0) % 180 !== 0 ? app.frame.height : app.frame.width
  const height = (app.frame.rotate || 0) % 180 !== 0 ? app.frame.width : app.frame.height
  const shortSide = Math.min(width, height) * (app.frame.scale || 1)
  zoom = Math.max(0.75, Math.min(2.25, Math.round((shortSide / 480) * 4) / 4))
  return {
    paper,
    width,
    height,
    scale: app.frame.scale || 1,
    embedded: app.frame.embedded === true,
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    tile: ink ? 'bg-white border-2 border-black' : 'bg-[#1a2030]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    accentText: ink ? 'text-black underline' : 'text-[#60a5fa]',
    press: paper ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    bar: ink ? 'bg-white text-black border-b-2 border-black' : 'bg-black/60 text-white',
    pageColor: ink ? '#ffffff' : '#0b0e14',
    folder: ink ? '#000000' : '#60a5fa',
  }
}

const Corners = ({ size, radius, color }) => {
  const s = Math.round(size * zoom)
  const r = Math.round(radius * zoom)
  return (
    <svg className="absolute inset-0" width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
      <path
        fill={color}
        fillRule="evenodd"
        d={`M0 0H${s}V${s}H0Z M${r} 0H${s - r}A${r} ${r} 0 0 1 ${s} ${r}V${s - r}A${r} ${r} 0 0 1 ${s - r} ${s}H${r}A${r} ${r} 0 0 1 0 ${s - r}V${r}A${r} ${r} 0 0 1 ${r} 0Z`}
      />
    </svg>
  )
}

const FolderGlyph = ({ size, color }) => (
  <svg viewBox="0 0 48 40" className={`w-[${px(size)}] h-[${px(Math.round((size * 40) / 48))}]`}>
    <path fill={color} d="M2 6a4 4 0 0 1 4-4h12l5 5h19a4 4 0 0 1 4 4v23a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4Z" />
    <path fill="#ffffff" fillOpacity="0.25" d="M2 13h44v3H2Z" />
  </svg>
)

const FileGlyph = ({ size }) => (
  <svg viewBox="0 0 40 48" className={`w-[${px(Math.round((size * 40) / 48))}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="3" strokeLinejoin="round" d="M6 3h19l12 12v30H6Z M25 3v12h12" />
  </svg>
)

const Chevron = ({ size, left }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" d={left ? 'M15 5L8 12L15 19' : 'M9 5L16 12L9 19'} />
  </svg>
)

const Close = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" d="M6 6L18 18M18 6L6 18" />
  </svg>
)

const Play = ({ size, playing }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    {playing ? <path fill="currentColor" d="M6 5h4v14H6ZM14 5h4v14h-4Z" /> : <path fill="currentColor" d="M7 4.5L19 12L7 19.5Z" />}
  </svg>
)

function sizeText(bytes) {
  if (!(bytes >= 0)) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

function Tile({ look, path, size, onOpen }) {
  const name = baseName(path)
  const folder = path.endsWith('/')
  const ref = thumbs.get(path)
  return (
    <div className={`flex flex-col w-[${px(size)}] gap-[${px(6)}] ${look.press} rounded-[${px(12)}]`} onClick={onOpen}>
      <div className={`relative w-[${px(size)}] h-[${px(size)}]`}>
        {ref ? (
          <img className={`w-[${px(size)}] h-[${px(size)}] object-cover`} src={ref} />
        ) : (
          <div className={`flex flex-col items-center justify-center gap-[${px(4)}] w-[${px(size)}] h-[${px(size)}] rounded-[${px(12)}] ${look.tile} ${look.muted}`}>
            {folder ? <FolderGlyph size={Math.round(size * 0.42)} color={look.folder} /> : isImage(name) ? null : <FileGlyph size={Math.round(size * 0.34)} />}
            {!folder && !isImage(name) ? <span className={`text-[${px(11)}] font-bold uppercase`}>{extOf(name)}</span> : null}
          </div>
        )}
        {ref ? <Corners size={size} radius={12} color={look.pageColor} /> : null}
      </div>
      <span className={`text-[${px(13)}] text-center truncate px-[${px(2)}]`}>{name}</span>
    </div>
  )
}

function Viewer({ look, spot, pictures, save }) {
  const at = Math.max(0, pictures.indexOf(spot.open))
  const close = () => {
    spot.open = ''
    spot.playing = false
    // Back to the page the picture is on.
    save(spot)
  }
  const step = (by) => {
    if (pictures.length === 0) return
    spot.open = pictures[(at + by + pictures.length) % pictures.length]
    slideAt = Date.now()
    save(spot)
  }
  const ref = viewer.path === spot.open ? viewer.ref : null
  const name = baseName(spot.open)
  const button = `flex items-center justify-center w-[${px(44)}] h-[${px(44)}] rounded-full ${look.paper ? look.soft : 'bg-black/50 text-white'} ${look.press}`
  return (
    <div
      className={`relative flex items-center justify-center w-full h-full ${look.paper ? 'bg-white' : 'bg-black'}`}
      onClick={() => {
        chrome = !chrome
      }}
      onSwipe={(e) => {
        if (e.direction === 'left') step(1)
        else if (e.direction === 'right') step(-1)
        else if (e.direction === 'down') close()
      }}
    >
      {ref ? (
        <img className="w-full h-full object-contain" src={ref} />
      ) : (
        <span className={`text-[${px(16)}] ${look.muted}`}>{failedThumbs.has('view:' + spot.open) ? 'This picture cannot be shown.' : 'Opening…'}</span>
      )}
      {chrome || look.paper ? (
        <div className={`absolute top-0 left-0 right-0 flex items-center gap-[${px(10)}] h-[${px(56)}] px-[${px(12)}] ${look.bar}`}>
          <div className={button} onClick={close}>
            <Close size={20} />
          </div>
          <div className={`flex flex-col flex-1 min-w-0`}>
            <span className={`text-[${px(15)}] font-bold truncate`}>{name}</span>
            <span className={`text-[${px(12)}] ${look.paper ? '' : 'text-white/70'} truncate`}>
              {[`${at + 1} of ${pictures.length}`, sizeText(frameos.assetSize(spot.open))].filter(Boolean).join(' · ')}
            </span>
          </div>
          {pictures.length > 1 ? (
            <div
              className={button}
              onClick={() => {
                spot.playing = !spot.playing
                slideAt = Date.now()
                save(spot)
              }}
            >
              <Play size={18} playing={spot.playing} />
            </div>
          ) : null}
        </div>
      ) : null}
      {(chrome || look.paper) && pictures.length > 1 ? (
        <div className={`absolute left-[${px(12)}] top-[${px(Math.round(look.height / zoom / 2) - 22)}] ${button}`} onClick={() => step(-1)}>
          <Chevron size={22} left />
        </div>
      ) : null}
      {(chrome || look.paper) && pictures.length > 1 ? (
        <div className={`absolute right-[${px(12)}] top-[${px(Math.round(look.height / zoom / 2) - 22)}] ${button}`} onClick={() => step(1)}>
          <Chevron size={22} />
        </div>
      ) : null}
    </div>
  )
}

export function get(app) {
  const look = lookOf(app)
  const spot = readSpot(app)
  spot.dir = typeof spot.dir === 'string' ? spot.dir : ''
  spot.page = Math.max(1, spot.page || 1)
  const save = (next) => saveSpot(next)
  let entries = entriesOf(spot.dir)
  // A folder that went away: back to the top.
  const parent = spot.dir.includes('/') ? spot.dir.slice(0, spot.dir.lastIndexOf('/')) : ''
  if (entries.length === 0 && spot.dir && !entriesOf(parent).includes(spot.dir + '/')) {
    spot.dir = ''
    spot.page = 1
    spot.open = ''
    entries = entriesOf('')
  }
  const pictures = entries.filter((path) => !path.endsWith('/') && isImage(path))

  // The picture open, at the screen's size; the one before goes.
  if (spot.open && pictures.includes(spot.open)) {
    if (spot.playing && pictures.length > 1) {
      if (slideAt === 0) slideAt = Date.now()
      if (Date.now() - slideAt >= SLIDE_SECONDS * 1000 - 500) {
        spot.open = pictures[(pictures.indexOf(spot.open) + 1) % pictures.length]
        slideAt = Date.now()
      }
      frameos.setNextSleep(Math.max(1, SLIDE_SECONDS - (Date.now() - slideAt) / 1000))
    }
    if (viewer.path !== spot.open) {
      if (viewer.ref) frameos.releaseImage(viewer.ref)
      const width = Math.round(look.width * look.scale)
      const height = Math.round(look.height * look.scale)
      const ref = frameos.loadAssetImage(spot.open, { keep: true, width, height, fit: 'contain' })
      viewer = { path: spot.open, ref }
      if (!ref) failedThumbs.add('view:' + spot.open)
    }
    save(spot)
    return <Viewer look={look} spot={spot} pictures={pictures} save={save} />
  }
  if (spot.open) spot.open = ''

  // The grid: square tiles with their names, as many as fit.
  const pad = 16
  const gap = 14
  const label = 24
  const headerHeight = 60
  const footerHeight = 46
  const roomWidth = look.width / zoom - pad * 2
  const roomHeight = look.height / zoom - headerHeight - footerHeight
  let cols = 2
  let rows = 1
  let size = 0
  let best = -1
  for (let r = 1; r <= 6; r++) {
    for (let c = 2; c <= 8; c++) {
      const s = Math.floor(Math.min((roomWidth - gap * (c - 1)) / c, (roomHeight - gap * (r - 1)) / r - label))
      const score = s >= 96 && s <= 220 ? r * c * Math.pow(s, 1.2) : -1
      if (score > best) {
        best = score
        cols = c
        rows = r
        size = s
      }
    }
  }
  if (best < 0) size = Math.floor((roomWidth - gap) / 2)
  const perPage = cols * rows
  const pages = Math.max(1, Math.ceil(entries.length / perPage))
  spot.page = Math.min(spot.page, pages)
  const shown = entries.slice((spot.page - 1) * perPage, spot.page * perPage)
  save(spot)

  // Thumbnails: none on the pass that shows a page, then one a pass (all at
  // once on e-paper, which draws once).
  const decode = Math.round(size * zoom * look.scale)
  const limit = look.embedded ? 24 : 48
  const missing = shown.filter((path) => !path.endsWith('/') && isImage(path) && !thumbs.has(path) && !failedThumbs.has(path))
  const pageKey = `${spot.dir}:${spot.page}:${perPage}`
  if (missing.length > 0) {
    if (look.paper) missing.forEach((path) => loadThumb(path, decode, limit))
    else if (pageKey === lastPageKey) loadThumb(missing[0], decode, limit)
  }
  lastPageKey = pageKey
  if (!look.paper && missing.some((path) => !thumbs.has(path) && !failedThumbs.has(path))) frameos.setNextSleep(0.05)

  const go = (change) => {
    Object.assign(spot, change)
    save(spot)
  }
  const open = (path) => {
    if (path.endsWith('/')) go({ dir: path.replace(/\/$/, ''), page: 1 })
    else if (isImage(path)) {
      chrome = true
      go({ open: path })
    }
  }
  const up = () => {
    const parts = spot.dir.split('/')
    parts.pop()
    go({ dir: parts.join('/'), page: 1 })
  }
  const turn = (by) => {
    const page = spot.page + by
    if (page >= 1 && page <= pages) go({ page })
  }

  const crumbs = ['Assets', ...(spot.dir ? spot.dir.split('/') : [])]
  const rowsOf = []
  for (let r = 0; r < rows; r++) {
    const row = shown.slice(r * cols, r * cols + cols)
    if (row.length === 0) break
    rowsOf.push(
      <div className={`flex gap-[${px(gap)}]`}>
        {row.map((path) => (
          <Tile look={look} path={path} size={size} onOpen={() => open(path)} />
        ))}
      </div>
    )
  }
  const gridWidth = cols * size + (cols - 1) * gap
  const arrow = (enabled) =>
    `flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${enabled ? `${look.soft} ${look.press}` : `${look.muted} opacity-40`}`

  return (
    <div className={`flex flex-col w-full h-full ${look.bg} ${look.text}`}>
      <div className={`flex items-center gap-[${px(10)}] h-[${px(headerHeight)}] px-[${px(pad)}] shrink-0`}>
        {spot.dir ? (
          <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] ${look.soft} ${look.press} shrink-0`} onClick={up}>
            <Chevron size={20} left />
          </div>
        ) : (
          <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] ${look.accent} shrink-0`}>
            <FolderGlyph size={22} color="#ffffff" />
          </div>
        )}
        <div className={`flex items-center gap-[${px(6)}] flex-1 min-w-0`}>
          {crumbs.map((crumb, i) => {
            const last = i === crumbs.length - 1
            const target = crumbs.slice(1, i + 1).join('/')
            return [
              i > 0 ? <span className={`text-[${px(18)}] ${look.muted}`}>/</span> : null,
              <span
                className={`text-[${px(last ? 20 : 16)}] ${last ? 'font-bold' : look.accentText} truncate ${i === 0 && crumbs.length > 3 ? 'shrink-0' : ''}`}
                onClick={last ? undefined : () => go({ dir: target, page: 1 })}
              >
                {crumb}
              </span>,
            ]
          })}
        </div>
        <span className={`text-[${px(13)}] ${look.muted} whitespace-nowrap`}>
          {pictures.length > 0 ? `${pictures.length} picture${pictures.length === 1 ? '' : 's'}` : ''}
        </span>
      </div>
      <div
        className={`flex flex-col flex-1 min-h-0 items-center px-[${px(pad)}]`}
        onSwipe={(e) => {
          if (e.direction === 'left') turn(1)
          else if (e.direction === 'right') turn(-1)
        }}
      >
        {entries.length === 0 ? (
          <div className={`flex flex-col items-center justify-center flex-1 self-stretch gap-[${px(8)}] ${look.muted}`}>
            <FolderGlyph size={56} color={look.folder} />
            <span className={`text-[${px(16)}]`}>{spot.dir ? 'Nothing in this folder.' : 'The assets folder is empty.'}</span>
          </div>
        ) : (
          <div className={`flex flex-col gap-[${px(gap)}] w-[${px(gridWidth)}]`}>{rowsOf}</div>
        )}
      </div>
      <div className={`flex items-center justify-end gap-[${px(6)}] h-[${px(footerHeight)}] px-[${px(pad)}] shrink-0`}>
        {pages > 1 ? [
          <div className={arrow(spot.page > 1)} onClick={() => turn(-1)}>
            <Chevron size={18} left />
          </div>,
          <span className={`w-[${px(72)}] text-center text-[${px(13)}] ${look.muted}`}>{`${spot.page} of ${pages}`}</span>,
          <div className={arrow(spot.page < pages)} onClick={() => turn(1)}>
            <Chevron size={18} />
          </div>,
        ] : null}
      </div>
    </div>
  )
}
